const body = $('Webhook - Receive Scan').first().json.body || {};
const p = $input.first().json;
const STAGES = ['NonDemented','VeryMildDemented','MildDemented','ModerateDemented'];
const P = p.prediction, conf = P.confidence;
const band = conf >= 0.85 ? 'high' : conf >= 0.6 ? 'moderate' : 'low';
const prev = (p.history || [])[0];
let trend = { has_previous: false };
if (prev) {
  const d = STAGES.indexOf(P.stage) - STAGES.indexOf(prev.stage);
  trend = { has_previous: true, previous_stage: prev.stage, previous_date: prev.date, previous_confidence: prev.confidence,
            change: d > 0 ? 'progressed' : d < 0 ? 'improved' : 'unchanged', stages_changed: Math.abs(d), scans_on_record: p.history.length + 1 };
}
const NEXT = {
  NonDemented: ['No imaging pattern suggestive of dementia was flagged by the model.', 'Continue routine check-ups as advised by a clinician.'],
  VeryMildDemented: ['Subtle early changes were flagged; discuss with a neurologist or memory clinic.', 'Clinician-administered cognitive screening is commonly used to follow up.'],
  MildDemented: ['Consult a neurologist for clinical evaluation and cognitive testing.', 'Discuss support planning and home safety with the care team.'],
  ModerateDemented: ['Prompt specialist evaluation is advised.', 'Involve family or caregivers in care planning and daily-living support.']
};
const recommendations = [...NEXT[P.stage], 'This is a model screening output; a qualified clinician must confirm any finding.'];
const state = { case_id: body.case_id || 'CASE-' + Date.now(), patient: { id: p.patient_id, name: p.patient_name }, prediction: P,
  region: p.region, region_note: p.region_note, gradcam_png_base64: p.gradcam_png_base64, trend, recommendations,
  clinical_note: body.clinical_note || '', confidence_band: band, attempt: 0, feedback: [] };
if (conf < 0.55 && !body.force) {
  state.needs_clarification = true;
  state.question = `The model is only ${(conf*100).toFixed(1)}% confident (${P.stage}). Upload a clearer axial MRI slice, or proceed to get a report clearly marked as low-confidence.`;
} else state.needs_clarification = false;
return [{ json: state }];

const s = $json;
const pct = v => +(v * 100).toFixed(1);
const facts = { patient_name: s.patient.name, stage: s.prediction.stage, confidence_pct: pct(s.prediction.confidence),
  probabilities_pct: Object.fromEntries(Object.entries(s.prediction.probabilities).map(([k, v]) => [k, pct(v)])),
  confidence_band: s.confidence_band, gradcam_region: s.region_note, trend: s.trend, clinical_note: s.clinical_note };
const sys = 'You write a cautious AI-screening report for an academic brain-MRI classifier. Use ONLY the facts JSON. Never invent numbers, stages, measurements or history. Never state a diagnosis; use wording like "the model predicts" and "consistent with". Return a JSON object with string keys: summary, findings, interpretation, trend_commentary, limitations (2-3 sentences each). If trend.has_previous is false, trend_commentary must say no earlier scan is on record. If confidence_band is low, say the result should be treated cautiously.';
let user = 'FACTS:\n' + JSON.stringify(facts);
if (s.feedback && s.feedback.length) user += '\n\nYour previous draft was rejected by the reviewer: ' + s.feedback.join('; ') + '. Fix every issue and return the full JSON again.';
return [{ json: { ...s, ollamaRequest: { model: 'llama3.1:8b', stream: false, format: 'json', options: { temperature: 0.2 },
  messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] } } }];

let s; try { s = $('Build Writer Request').item.json; } catch (e) { s = $('Build Writer Request').last().json; }
const raw = ($input.first().json.message || {}).content || '';
const KEYS = ['summary','findings','interpretation','trend_commentary','limitations'];
let draft = null, issues = [];
try { draft = JSON.parse(raw); } catch (e) { issues.push('Output was not valid JSON'); }
if (draft) {
  for (const k of KEYS) if (typeof draft[k] !== 'string' || draft[k].trim().length < 20) issues.push('Missing or too short section: ' + k);
  const text = KEYS.map(k => String(draft[k] || '')).join(' ');
  const allowed = [s.prediction.confidence * 100, ...Object.values(s.prediction.probabilities).map(v => v * 100)];
  (text.match(/\d+(?:\.\d+)?\s*%/g) || []).forEach(m => { const n = parseFloat(m); if (!allowed.some(a => Math.abs(a - n) <= 0.6)) issues.push('Percentage ' + m + ' is not in the supplied facts'); });
  if (!String(draft.summary || '').toLowerCase().replace(/\s/g, '').includes(s.prediction.stage.toLowerCase())) issues.push('Summary must name the predicted stage ' + s.prediction.stage);
  if (/(diagnos(ed|is) with|has alzheimer|you have|confirmed (alzheimer|dementia))/i.test(text)) issues.push('Contains diagnostic language; use "model predicts / consistent with"');
  if (!s.trend.has_previous && /(previous|earlier|prior) scan/i.test(String(draft.trend_commentary)) && !/no (earlier|previous|prior)/i.test(String(draft.trend_commentary))) issues.push('Mentions a previous scan but none is on record');
}
return [{ json: { ...s, draft, issues, review_passed: issues.length === 0, attempt: s.attempt + 1, feedback: issues } }];

const s = $json, P = s.prediction, pct = (P.confidence * 100).toFixed(1);
const FIND = { NonDemented: 'no notable atrophy pattern', VeryMildDemented: 'subtle, early structural changes',
  MildDemented: 'moderate structural changes, including some ventricular enlargement', ModerateDemented: 'pronounced atrophy with ventricular enlargement' };
let report = s.draft, source = 'llm_writer';
if (!s.review_passed) {
  source = 'template_fallback';
  report = { summary: `The model classified this scan as ${P.stage} with ${s.confidence_band} confidence (${pct}%).`,
    findings: `Model attention was concentrated in ${s.region_note}.`,
    interpretation: `This pattern is consistent with ${FIND[P.stage]}. It is a screening output, not a diagnosis.`,
    trend_commentary: s.trend.has_previous ? `Compared with the previous scan (${s.trend.previous_stage}, ${s.trend.previous_date}), the predicted stage has ${s.trend.change}.` : 'No earlier scan is on record for this patient.',
    limitations: 'Academic model, not clinically validated; the training dataset has known train/test overlap.' };
}
return [{ json: { case_id: s.case_id, patient: s.patient, created: new Date().toISOString(), prediction: P, region: s.region,
  gradcam_png_base64: s.gradcam_png_base64, trend: s.trend, recommendations: s.recommendations, report, report_source: source,
  review: { passed: s.review_passed, attempts: s.attempt, issues: s.issues },
  approval: { status: 'pending' }, disclaimer: 'Educational AI-generated screening report. Not a medical device and not a diagnosis; must be reviewed by a qualified clinician.' } }];
